test("AC-36 the criterion confusion matrix counts all sixteen cells and names the two that matter", () => {
  const pairs = [
    { criterionType: "lab", gold: UNKNOWN, predicted: SATISFIED },
    { criterionType: "lab", gold: SATISFIED, predicted: NOT_SATISFIED },
    { criterionType: "time_window", gold: SATISFIED, predicted: SATISFIED },
    { criterionType: "time_window", gold: NOT_SATISFIED, predicted: UNKNOWN },
    { criterionType: "prior_treatment", gold: PENDING_RECHECK, predicted: PENDING_RECHECK },
    { criterionType: "lab", gold: "nonsense", predicted: SATISFIED },
  ];
  const confusion = criterionConfusion(pairs);
  assert.equal(confusion.counted, 5, "a pair outside the vocabulary is not counted as agreement");
  assert.equal(confusion.unknownReadAsSatisfied, 1);
  assert.equal(confusion.satisfiedReadAsNotSatisfied, 1);
  assert.equal(confusion.matrix[NOT_SATISFIED][UNKNOWN], 1);
  assert.equal(confusion.agreement, 2 / 5);
  assert.equal(confusion.unknownRate, 1 / 5);
  assert.equal(confusion.byLayer.number.total, 2);
  assert.equal(confusion.byLayer.time.total, 2);
  assert.equal(errorLayer("time_window"), "time");
  assert.equal(errorLayer("pregnancy"), "applicability");
  assert.equal(errorLayer("something-else"), "other");
});

