  assert.equal(Object.hasOwn(report, "passed"), false);
  assert.match(report.note, /不设统一准确率门槛/);
  assert.match(report.ceiling.note, /不代表临床准确率上限/);
  assert.equal(report.reviewMinutes.savedPerChart, 5);
