test("AC-14 the contract refuses a package whose own judgments do not produce its summary", async () => {
  // This was a run-side `preflight.py` until the platform's rule caught up
  // with it: a checker that restates delivery rules is the copy that drifts
  // (clinicalEvidenceSingleImplementation.test.mjs). The same two properties
  // now live once, in `@evimed/domain`'s vcr contract, and the gate returns
  // them to the run — where a package built from this package's own evaluator
  // is the passing case, so it cannot drift from what the code produces.
  const { vcrMatchingFindings } = await import("@evimed/domain");
  const source = chart("男，67 岁。否认心梗史。");
  const assessment = assessSubject({
    subjectKey: "S1", asOf: AS_OF, documents: source.documents,
    criteria: [CRITERION_MI, {
      id: "crt-washout", kind: "exclusion", criterionType: "prior_treatment",
      requirement: { op: "elapsed_since", variable: "docetaxel", days: 28 },
    }],
    facts: [source.fact("否认心梗史", { variable: "myocardial_infarction", polarity: "negated" })],
  });
  const document = matchingAssessmentDocument(assessment);
  assert.equal(document.summary, "insufficient_evidence");

  const of = (/** @type {any} */ value) => vcrMatchingFindings({ files: new Map([["matching.json", JSON.stringify(value)]]) });
  const clean = of(document);
  assert.deepEqual(clean.issues.filter((issue) => issue.code === "vcr_summary_contradicted"), []);
  assert.equal(clean.metrics.vcrMatchingSummary, "insufficient_evidence");

  // The same package claiming 「符合」 over an unknown exclusion criterion.
  const contradicted = of({ ...document, summary: "eligible" });
  assert.ok(contradicted.issues.some((issue) => issue.code === "vcr_summary_contradicted"),
    "an unknown exclusion criterion never leaves a subject eligible");
  assert.ok(contradicted.issues.every((issue) => issue.severity === "advisory"),
    "the finding is returned to the run, never used to withhold the package");

  // And 「不适用」 written as a fifth state rather than as the field beside it.
  const fifthState = of({
    ...document, summary: "insufficient_evidence",
    judgments: [{ criterionId: "crt-x", state: "not_applicable", applicable: true, evidence: [] }],
  });
  assert.ok(fifthState.issues.some((issue) => issue.code === "vcr_judgment_state_unknown"));
  assert.equal(fifthState.metrics.vcrJudgmentsBadState, 1);
});

test("the eval pack carries real briefs, and every one of them names the input the manifest requires", async () => {
  const briefs = JSON.parse(await readFile(path.join(repoRoot, "evals", "vcr-matching", "briefs.json"), "utf8"));
  assert.equal(briefs.capability, "vcr-matching");
  assert.ok(briefs.briefs.length >= 3, `only ${briefs.briefs.length} briefs`);
  const ids = briefs.briefs.map((brief) => brief.id);
  assert.equal(new Set(ids).size, ids.length);
  for (const brief of briefs.briefs) {
    assert.ok(brief.inputs.studyId, brief.id);
    assert.ok(brief.mustDo.length >= 3 && brief.mustNotDo.length >= 3, brief.id);
  }
  // The two measurement briefs are the ones AC-36 and AC-37 are answered by.
  assert.ok(ids.some((id) => id.includes("historical-replay")), "AC-36 needs a replay brief");
  assert.ok(ids.some((id) => id.includes("accrual-forecast-backtest")), "AC-37 needs a backtest brief");
});

test('C2-25 declared code vocabulary versions cannot silently select the current mapping', () => {
  const node = { op: 'compare', variable: 'sex', comparator: 'eq', value: 'female' };
  const fact = { id: 'versioned', variable: 'sex', value: 'F', extractedBy: 'snapshot', source: { vocabularyVersion: 'unknown-vocabulary-2' } };
  const unknown = evaluateRequirement(node, { facts: [fact], asOf: Date.parse(AS_OF) });
  assert.equal(unknown.state, UNKNOWN);
  assert.equal(unknown.missing[0].reason, 'coding_version_unavailable');
  const assessed = assessSubject({ subjectKey: 'heldout', asOf: AS_OF, facts: [{ ...fact, visibleAt: AS_OF }], criteria: [{ id: 'sex', kind: 'inclusion', requirement: node }] });
  assert.equal(assessed.judgments[0].state, UNKNOWN);
  assert.ok(assessed.provenance.vocabularyVersion);
});


test('clinical context and medication states change eligibility without changing supported quotes', () => {
  const source = chart('父亲有心梗史。患者可能心梗。拟于2026-10-02使用多西他赛。');
  const metadata = { schema:1, assertion:'affirmed', experiencer:'family' };
  const assess = facts => assessSubject({ asOf:'2026-10-09', criteria:[{...CRITERION_MI,requirement:{op:'absent',variable:'myocardial_infarction'}}], facts,documents:source.documents });
  assert.equal(assess([source.fact('父亲有心梗史', {variable:'myocardial_infarction',clinical:metadata})]).summary,'insufficient_evidence');
  assert.equal(assess([source.fact('患者可能心梗', {variable:'myocardial_infarction',clinical:{...metadata,experiencer:'patient',assertion:'possible'}})]).summary,'insufficient_evidence');
  const washout={id:'washout',kind:'exclusion',requirement:{op:'elapsed_since',variable:'docetaxel',days:28}};
  for (const state of ['prescribed','planned','historical_list','unknown']) {
    const fact=source.fact('多西他赛',{variable:'docetaxel',occurredAt:'2026-08-01',clinical:{...metadata,experiencer:'patient',medication:{state}}});
    assert.equal(evaluateCriterion(washout,{facts:[fact],asOf:Date.parse('2026-10-09')}).state,UNKNOWN,state);
  }
  const copied=source.fact('多西他赛',{variable:'docetaxel',occurredAt:'2026-08-01',clinical:{...metadata,experiencer:'patient',copiedFrom:'original',medication:{state:'administered'}}});
  assert.equal(evaluateCriterion(washout,{facts:[copied],asOf:Date.parse('2026-10-09')}).state,UNKNOWN);
});

test('same-event conflicting lab results stay unknown; a visible sourced correction changes only the current view', () => {
  const source=chart('肌酐 1.2 mg/dL。复核肌酐 2.4 mg/dL。');
  const clinical={schema:1,assertion:'affirmed',experiencer:'patient',eventId:'sample_1'};
  const first=source.fact('肌酐 1.2 mg/dL',{id:'first',subjectKey:'p1',variable:'creatinine',value:1.2,unit:'mg/dL',clinical});
  const second=source.fact('复核肌酐 2.4 mg/dL',{id:'second',subjectKey:'p1',variable:'creatinine',value:2.4,unit:'mg/dL',clinical});
  const criteria=[{id:'lab',kind:'inclusion',requirement:{op:'compare',variable:'creatinine',comparator:'lte',value:1.5,unit:'mg/dL'}}];
  const assess=(facts,asOf='2026-10-09')=>assessSubject({criteria,facts,asOf,documents:source.documents});
  assert.equal(assess([first,second]).summary,'insufficient_evidence');
  const correction={...second,createdAt:'2026-10-02',clinical:{...clinical,correctionOf:'first',correctionReason:'Confirmed corrected report'}};
  assert.equal(assess([first,correction],'2026-10-01').summary,'eligible');
  assert.equal(assess([first,correction]).summary,'ineligible');
});

test('a model cannot attach a guessed unit to a quote that omits it, or bypass units with equality',()=>{
  const source=chart('2026-09-01患者血肌酐1.0，单位未记载。');
  const clinical={schema:1,assertion:'affirmed',experiencer:'patient',laboratory:{originalValue:1,originalUnit:'未给单位'}};
  const guessed=source.fact('血肌酐1.0',{variable:'creatinine',value:1,unit:'mg/dL',clinical});
  const verified=verifyFactEvidence(guessed,{documents:source.documents});
  assert.deepEqual(verified,{ok:false,reason:'unit_not_in_span'});
  const criterion={id:'lab',kind:'inclusion',requirement:{op:'compare',variable:'creatinine',comparator:'lte',value:1.5,unit:'mg/dL'}};
  assert.equal(assessSubject({criteria:[criterion],facts:[guessed],documents:source.documents,asOf:AS_OF}).summary,'insufficient_evidence');
  assert.equal(evaluateCriterion(criterion,{facts:[guessed],asOf:Date.parse(AS_OF)}).state,UNKNOWN);
  const equal={...criterion,requirement:{...criterion.requirement,comparator:'eq',value:88.4,unit:'umol/L'}};
  assert.equal(evaluateCriterion(equal,{facts:[{variable:'creatinine',value:1,unit:'mg/dL'}],asOf:Date.parse(AS_OF)}).state,SATISFIED);
  assert.equal(evaluateCriterion(equal,{facts:[{variable:'creatinine',value:88.4}],asOf:Date.parse(AS_OF)}).state,UNKNOWN);
});


test('a current medication denial does not establish absence throughout a lookback window',()=>{
  const criterion={id:'history',kind:'inclusion',requirement:{op:'absent',variable:'docetaxel',window:{days:30}}};
  const asOf=Date.parse('2026-10-09T00:00:00Z');
  const clinical={schema:1,assertion:'negated',experiencer:'patient',medication:{state:'unknown',absenceScope:'current'}};
  const fact={id:'denial',variable:'docetaxel',polarity:'negated',clinical};
  const evaluate=clinical=>evaluateCriterion(criterion,{facts:[{...fact,clinical}],asOf}).state;
  assert.equal(evaluate(clinical),UNKNOWN);
  assert.equal(evaluate({...clinical,medication:{state:'unknown',absenceScope:'never'}}),SATISFIED);
  const scoped={...clinical,medication:{state:'unknown',absenceScope:'interval'},occurredInterval:{start:'2026-09-09',end:'2026-10-09'}};
  assert.equal(evaluate(scoped),SATISFIED);
  assert.equal(evaluate({...scoped,occurredInterval:{start:'2026-09-10',end:'2026-10-09'}}),UNKNOWN);
  assert.equal(evaluate({...scoped,occurredInterval:{start:'2026-09-09',end:'2026-10-08'}}),UNKNOWN);
  assert.equal(evaluateCriterion(criterion,{facts:[{...fact,clinical:null}],asOf}).state,SATISFIED);
});
